create extension if not exists pgcrypto;
create table if not exists public.invitados (id uuid primary key default gen_random_uuid(),codigo text not null unique,nombre text not null,apellido text not null default '',invitado_por text not null default '',cuenta_pago text not null default '',pagado boolean not null default false,fecha_ingreso timestamptz null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.registro_entradas (id bigint generated by default as identity primary key,invitado_id uuid null references public.invitados(id) on delete set null,codigo text,invitado_nombre text,resultado text not null,usuario_id uuid null default auth.uid(),created_at timestamptz not null default now());
create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
drop trigger if exists trg_invitados_updated on public.invitados;create trigger trg_invitados_updated before update on public.invitados for each row execute function public.touch_updated_at();
alter table public.invitados enable row level security;alter table public.registro_entradas enable row level security;
drop policy if exists authenticated_all_invitados on public.invitados;create policy authenticated_all_invitados on public.invitados for all to authenticated using (true) with check (true);
drop policy if exists authenticated_read_logs on public.registro_entradas;create policy authenticated_read_logs on public.registro_entradas for select to authenticated using (true);
revoke insert,update,delete on public.registro_entradas from anon,authenticated;grant select on public.registro_entradas to authenticated;grant select,insert,update,delete on public.invitados to authenticated;
create or replace function public.validar_y_registrar_entrada(p_codigo text) returns table(resultado text,nombre text,apellido text,fecha_ingreso timestamptz) language plpgsql security definer set search_path=public as $$ declare v public.invitados%rowtype; begin if auth.uid() is null then raise exception 'No autenticado'; end if;select * into v from public.invitados where codigo=p_codigo for update;if not found then insert into public.registro_entradas(codigo,resultado,usuario_id) values(p_codigo,'NO_EXISTE',auth.uid());return query select 'NO_EXISTE'::text,null::text,null::text,null::timestamptz;return;end if;if not v.pagado then insert into public.registro_entradas(invitado_id,codigo,invitado_nombre,resultado,usuario_id) values(v.id,v.codigo,trim(v.nombre||' '||v.apellido),'NO_PAGADO',auth.uid());return query select 'NO_PAGADO'::text,v.nombre,v.apellido,v.fecha_ingreso;return;end if;if v.fecha_ingreso is not null then insert into public.registro_entradas(invitado_id,codigo,invitado_nombre,resultado,usuario_id) values(v.id,v.codigo,trim(v.nombre||' '||v.apellido),'YA_UTILIZADO',auth.uid());return query select 'YA_UTILIZADO'::text,v.nombre,v.apellido,v.fecha_ingreso;return;end if;update public.invitados set fecha_ingreso=now() where id=v.id returning public.invitados.fecha_ingreso into v.fecha_ingreso;insert into public.registro_entradas(invitado_id,codigo,invitado_nombre,resultado,usuario_id) values(v.id,v.codigo,trim(v.nombre||' '||v.apellido),'ACCESO_PERMITIDO',auth.uid());return query select 'ACCESO_PERMITIDO'::text,v.nombre,v.apellido,v.fecha_ingreso;end $$;
create or replace function public.revertir_entrada(p_invitado_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v public.invitados%rowtype; begin if auth.uid() is null then raise exception 'No autenticado'; end if;select * into v from public.invitados where id=p_invitado_id for update;if not found then raise exception 'Invitado no encontrado'; end if;update public.invitados set fecha_ingreso=null where id=p_invitado_id;insert into public.registro_entradas(invitado_id,codigo,invitado_nombre,resultado,usuario_id) values(v.id,v.codigo,trim(v.nombre||' '||v.apellido),'ENTRADA_REVERTIDA',auth.uid());end $$;
revoke all on function public.validar_y_registrar_entrada(text) from public,anon;grant execute on function public.validar_y_registrar_entrada(text) to authenticated;revoke all on function public.revertir_entrada(uuid) from public,anon;grant execute on function public.revertir_entrada(uuid) to authenticated;
do $$ begin alter publication supabase_realtime add table public.invitados; exception when duplicate_object then null; end $$;do $$ begin alter publication supabase_realtime add table public.registro_entradas; exception when duplicate_object then null; end $$;
